import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(__file__)))
from dsl import *
U("s4-u15")
C = "A2-B1"
# Lições de aprofundamento (10–21): conectores para ligar frases e organizar textos.

L(10, "Sequência: allereerst, vervolgens, ten slotte", "Instructies stap voor stap.",
  ["Ordenar passos de uma instrução com conectores de sequência"],
  vocab=[V("v-allereerst","allereerst","antes de mais|em primeiro lugar","adverb"), V("v-vervolgens","vervolgens","em seguida","adverb"),
         V("v-ten-slotte","ten slotte","por fim","expression"), V("v-downloaden","downloaden","descarregar","verb")],
  ex=[("Allereerst download je de app.","Antes de mais, descarregas a aplicação."),("Vervolgens maak je een account aan.","Em seguida crias uma conta."),("Ten slotte kies je een wachtwoord.","Por fim escolhes uma palavra-passe.")],
  review=["v-eerst","v-daarna","v-stap-voor-stap"],
  cefr=C, exs=[
    MA([("allereerst","antes de mais"),("vervolgens","em seguida"),("ten slotte","por fim"),("downloaden","descarregar")], "Sequência.", ["v-allereerst","v-vervolgens","v-ten-slotte","v-downloaden"]),
    MC("Qual é a ordem natural?", ["*allereerst → vervolgens → ten slotte","ten slotte → allereerst → vervolgens|Não.","vervolgens → ten slotte → allereerst|Não."], "Início → meio → fim.", ["v-allereerst","v-vervolgens","v-ten-slotte"]),
    CO("text","Zo vraag je een DigiD aan", "Allereerst ga je naar de website van DigiD en klik je op «aanvragen». Vervolgens vul je je burgerservicenummer, geboortedatum en adres in. Daarna kies je een gebruikersnaam en een wachtwoord. Binnen een paar dagen ontvang je een brief met een activeringscode. Ten slotte activeer je je DigiD met die code.",
       [("O que se faz em primeiro lugar?", ["*Ir ao site e clicar em «aanvragen»","Esperar a carta","Escolher a palavra-passe"]),("Como chega o código?", ["*Por carta","Por SMS","Por e-mail"]),("Qual é o último passo?", ["*Ativar com o código","Ligar à câmara","Ir ao banco"])],
       "Instruções com conectores (o processo real pode mudar: confirme no site oficial).", ["v-allereerst","v-vervolgens","v-ten-slotte"]),
    TR("pt-nl","Em seguida crias uma conta.", ["Vervolgens maak je een account aan","Daarna maak je een account aan"], "Inversão depois do conector.", ["v-vervolgens"]),
    TR("pt-nl","Por fim escolhes uma palavra-passe.", ["Ten slotte kies je een wachtwoord","Tot slot kies je een wachtwoord"], "Inversão.", ["v-ten-slotte"]),
    FE(["Vervolgens","je","vult","je","adres","in."], 1, "vul", "Inversão: Vervolgens vul je… (verbo sem -t antes de je).", ["v-vervolgens"]),
    FB("___ download je de app uit de app store.", ["Allereerst"], "Primeiro passo.", ["v-allereerst"], choices=["Allereerst","Ten slotte","Vervolgens"], tr="Antes de mais, descarregas a aplicação da loja."),
    CJ("downloaden","ik","Ik heb de app al ___.", ["gedownload"], "ge-download (sem -d extra).", ["v-downloaden"], tense="passado-perfeito"),
    LI("Vervolgens vul je je gegevens in en klik je op verzenden.", ["Vervolgens vul je je gegevens in en klik je op verzenden"], "Em seguida preenches os teus dados e clicas em enviar.", "Dois verbos com inversão.", ["v-vervolgens"]),
    WO("Antes de mais, descarregas a aplicação.", ["Allereerst","download","je","de","app"], "Inversão.", ["v-allereerst"]),
  ], diff=3, mins=7)

L(11, "Acrescentar: daarnaast, bovendien, niet alleen … maar ook", "Niet alleen goedkoop, maar ook gezond.",
  ["Acrescentar argumentos e informação"],
  vocab=[V("v-daarnaast","daarnaast","além disso","adverb"), V("v-niet-alleen-maar-ook","niet alleen … maar ook","não só … mas também","expression"),
         V("v-tevens","tevens","também (formal)","adverb")],
  ex=[("Fietsen is niet alleen goedkoop, maar ook gezond.","Andar de bicicleta não só é barato, como também saudável."),("Daarnaast is het goed voor het milieu.","Além disso, é bom para o ambiente."),("Hij is tevens voorzitter van de club.","Ele é também presidente do clube.")],
  review=["v-bovendien"],
  cefr=C, exs=[
    MA([("daarnaast","além disso"),("niet alleen … maar ook","não só … mas também"),("tevens","também (formal)"),("bovendien","além do mais")], "Adição.", ["v-daarnaast","v-niet-alleen-maar-ook","v-tevens","v-bovendien"]),
    MC("Qual destes é o mais formal?", ["*tevens","ook|Neutro.","en|Básico."], "tevens = formal.", ["v-tevens"]),
    TR("pt-nl","Além disso, é bom para o ambiente.", ["Daarnaast is het goed voor het milieu","Bovendien is het goed voor het milieu"], "Inversão.", ["v-daarnaast"]),
    BS("Não só é barato, como também saudável.", ["Het","is","niet","alleen","goedkoop,","maar","ook","gezond","maar"], ["Het is niet alleen goedkoop, maar ook gezond"], "niet alleen … maar ook.", ["v-niet-alleen-maar-ook"]),
    CO("text","Waarom ik in Leiden woon", "Leiden is een prachtige stad. Niet alleen zijn er veel grachten en oude gebouwen, maar er is ook een gezellige markt. Daarnaast ligt de stad dicht bij het strand. Bovendien kun je in twintig minuten met de trein in Amsterdam of Den Haag zijn. Het enige nadeel: de huren zijn hoog.",
       [("O que há além dos canais?", ["*Um mercado agradável","Montanhas","Um aeroporto"]),("Que vantagem de localização?", ["*Perto da praia e de outras cidades","Fica no centro do país","Tem metro"]),("Qual é a desvantagem?", ["*As rendas altas","O tempo","O barulho"])],
       "Acumular argumentos.", ["v-daarnaast","v-niet-alleen-maar-ook"]),
    FE(["Daarnaast","het","is","goedkoop."], 1, "is", "Inversão: Daarnaast is het goedkoop.", ["v-daarnaast"]),
    FB("De cursus is ___ alleen leuk, maar ook nuttig.", ["niet"], "niet alleen … maar ook.", ["v-niet-alleen-maar-ook"], choices=["niet","geen","wel"], tr="O curso não só é giro, como também útil."),
    LI("Daarnaast werk ik twee dagen per week als vrijwilliger.", ["Daarnaast werk ik twee dagen per week als vrijwilliger"], "Além disso, trabalho dois dias por semana como voluntário.", "Inversão.", ["v-daarnaast"]),
    TR("nl-pt","Hij is tevens voorzitter van de club.", ["Ele é também presidente do clube","Ele também é presidente do clube"], "tevens.", ["v-tevens"]),
    WO("Além disso, é perto da praia.", ["Daarnaast","ligt","het","dicht","bij","het","strand"], "Inversão.", ["v-daarnaast"]),
  ], diff=3, mins=6)

L(12, "Contraste: echter, daarentegen", "Het plan is goed; het is echter duur.",
  ["Exprimir contraste de forma mais elaborada"],
  vocab=[V("v-echter","echter","no entanto","adverb"), V("v-daarentegen","daarentegen","em contrapartida|por outro lado","adverb"),
         V("v-desondanks","desondanks","apesar disso","adverb")],
  ex=[("Het plan is goed. Het is echter duur.","O plano é bom. No entanto, é caro."),("Amsterdam is druk; Groningen daarentegen is rustig.","Amesterdão é movimentada; Groningen, em contrapartida, é calma."),("Het regende. Desondanks gingen we wandelen.","Choveu. Apesar disso fomos passear.")],
  review=["v-maar-conj","v-toch-conj","v-in-tegenstelling-tot"],
  gram=[G("g-echter","Echter e daarentegen","**Echter** (no entanto) e **daarentegen** (em contrapartida) são advérbios: podem vir no início (com inversão) ou **depois do verbo**: *Het is **echter** duur.* *Groningen is **daarentegen** rustig.* No início: *Echter, …* é pouco natural; prefira-se a posição no meio da frase.",
    [("De prijs is echter hoog.","O preço, no entanto, é alto."),("Mijn broer houdt van vlees; ik daarentegen eet vegetarisch.","O meu irmão gosta de carne; eu, em contrapartida, como vegetariano.")])],
  cefr=C, exs=[
    MA([("echter","no entanto"),("daarentegen","em contrapartida"),("desondanks","apesar disso"),("maar","mas")], "Contraste.", ["v-echter","v-daarentegen","v-desondanks","v-maar-conj"]),
    MC("Qual é a posição mais natural de «echter»?", ["*Het is echter duur.","Echter het is duur.|Sem inversão e pouco natural.","Het is duur echter.|Pouco natural."], "Depois do verbo.", ["v-echter"]),
    TR("pt-nl","Choveu. Apesar disso fomos passear.", ["Het regende. Desondanks gingen we wandelen","Het regende. Toch gingen we wandelen","Het regende, desondanks gingen we wandelen"], "Inversão depois de desondanks.", ["v-desondanks"]),
    TR("pt-nl","O plano é bom. No entanto, é caro.", ["Het plan is goed. Het is echter duur","Het plan is goed, maar het is duur","Het plan is goed. Het is wel duur"], "echter no meio.", ["v-echter"]),
    CO("text","Twee steden vergeleken", "Rotterdam is een moderne stad met wolkenkrabbers en veel internationale bedrijven. Utrecht daarentegen heeft een historisch centrum met grachten en werfkelders. In beide steden zijn de huren hoog. Rotterdam is echter iets goedkoper dan Utrecht. Desondanks kiezen veel studenten voor Utrecht, vanwege de universiteit.",
       [("Como é Utrecht, por contraste?", ["*Tem um centro histórico","É muito moderna","Não tem canais"]),("Qual é mais barata?", ["*Roterdão (um pouco)","Utrecht","São iguais"]),("Porque escolhem os estudantes Utrecht?", ["*Por causa da universidade","Porque é barata","Por causa do porto"])],
       "Comparar com echter/daarentegen/desondanks.", ["v-daarentegen","v-echter","v-desondanks"]),
    FE(["Het","was","koud.","Desondanks","we","gingen","zwemmen."], 4, "gingen", "Inversão: Desondanks gingen we…", ["v-desondanks"]),
    FB("Ik drink koffie; mijn vrouw ___ drinkt alleen thee.", ["daarentegen"], "Em contrapartida.", ["v-daarentegen"], choices=["daarentegen","desondanks","tevens"], tr="Eu bebo café; a minha mulher, em contrapartida, só bebe chá."),
    LI("De service was goed, het eten was echter koud.", ["De service was goed, het eten was echter koud","De service was goed het eten was echter koud"], "O serviço era bom, mas a comida estava fria.", "echter no meio.", ["v-echter"]),
    WO("No entanto, é caro.", ["Het","is","echter","duur"], "echter depois do verbo.", ["v-echter"]),
  ], diff=4, mins=7)

L(13, "Causa e consequência", "Als gevolg van de storm … Daardoor …",
  ["Ligar causas e consequências com conectores variados"],
  vocab=[V("v-als-gevolg-van","als gevolg van","em consequência de","expression"), V("v-om-die-reden","om die reden","por essa razão","expression"),
         V("v-zodoende","zodoende","dessa forma|assim","adverb")],
  ex=[("Als gevolg van de storm vielen er bomen om.","Em consequência da tempestade caíram árvores."),("De trein reed niet. Om die reden kwam ik te laat.","O comboio não circulou. Por essa razão cheguei atrasado."),("Ik heb hard gestudeerd en zodoende ben ik geslaagd.","Estudei muito e assim passei.")],
  review=["v-daardoor","v-dus-conj","v-daarom","v-door"],
  cefr=C, exs=[
    MA([("als gevolg van","em consequência de"),("om die reden","por essa razão"),("zodoende","dessa forma"),("daardoor","por isso (causa)")], "Causa e efeito.", ["v-als-gevolg-van","v-om-die-reden","v-zodoende","v-daardoor"]),
    MC("Qual é seguido de um NOME (não de uma frase)?", ["*als gevolg van","daardoor|Advérbio + frase.","om die reden|Advérbio + frase."], "als gevolg van + nome.", ["v-als-gevolg-van"]),
    TR("pt-nl","Em consequência da tempestade caíram árvores.", ["Als gevolg van de storm vielen er bomen om","Door de storm vielen er bomen om"], "als gevolg van + nome.", ["v-als-gevolg-van"]),
    TR("pt-nl","Por essa razão cheguei atrasado.", ["Om die reden kwam ik te laat","Daarom kwam ik te laat","Om die reden ben ik te laat gekomen"], "Inversão.", ["v-om-die-reden"]),
    CO("text","Nieuwsbericht", "Als gevolg van de hevige regenval stonden gisteren veel straten in Maastricht onder water. Daardoor reden er geen bussen in het centrum. Scholen bleven om die reden gesloten. De brandweer heeft de hele nacht gepompt; zodoende is het water nu grotendeels weg.",
       [("Qual foi a causa?", ["*Chuva intensa","Um incêndio","Uma greve"]),("O que aconteceu aos autocarros?", ["*Não circularam no centro","Andaram mais devagar","Foram grátis"]),("Porque desapareceu a água?", ["*Os bombeiros bombearam toda a noite","Parou de chover","Secou com o sol"])],
       "Notícia com causa/consequência.", ["v-als-gevolg-van","v-om-die-reden","v-zodoende"]),
    FE(["Als","gevolg","van","de","staking","rijdt","er","geen","treinen."], 5, "rijden", "Sujeito plural (treinen): rijden.", ["v-als-gevolg-van"]),
    FB("Ik had geen geld; om die ___ bleef ik thuis.", ["reden"], "om die reden.", ["v-om-die-reden"], choices=["reden","gevolg","oorzaak"], tr="Não tinha dinheiro; por essa razão fiquei em casa."),
    MC("«Daardoor» e «daarom» — qual dá uma razão/decisão?", ["*daarom","daardoor|Indica causa (sem intenção).","nenhum|Não."], "Como omdat/doordat.", ["v-daarom","v-daardoor"]),
    LI("Er was een ongeluk; daardoor stond er een lange file.", ["Er was een ongeluk; daardoor stond er een lange file","Er was een ongeluk, daardoor stond er een lange file","Er was een ongeluk daardoor stond er een lange file"], "Houve um acidente; por isso havia uma longa fila.", "Inversão.", ["v-daardoor"]),
    WO("Por essa razão fiquei em casa.", ["Om","die","reden","bleef","ik","thuis"], "Inversão.", ["v-om-die-reden"]),
  ], diff=4, mins=7)

