    TR("pt-nl","Já moro há cinco anos nos Países Baixos.", ["Ik woon inmiddels vijf jaar in Nederland","Inmiddels woon ik vijf jaar in Nederland","Ik woon al vijf jaar in Nederland"], "inmiddels.", ["v-inmiddels"]),
    TR("pt-nl","Tu pões a mesa, enquanto isso eu cozinho.", ["Jij dekt de tafel, ondertussen kook ik","Jij dekt de tafel, intussen kook ik"], "Inversão.", ["v-ondertussen"]),
